     4	/**
     5	 * The MHPCO's item-specific risk surcharges. A surcharge is charged only for
     6	 * the items that carry the risk, and is measured against that item's own base
     7	 * premium -- never against the policy total.
     8	 */
     9	public final class ItemRiskSurcharges {
    10	
    11	    private static final int CURSE_SURCHARGE_PERCENT = 50;
    12	
    13	    private static final int HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
    14	
    15	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    16	
    17	    private ItemRiskSurcharges() {
    18	    }
    19	
    20	    /**
    21	     * Cursed items add a 50 % risk surcharge on their own base premium.
    22	     */
    23	    public static int curseSurcharge(List<Item> items) {
    24	        return surchargeOnItemsAtRisk(items, Item::cursed, CURSE_SURCHARGE_PERCENT);
    25	    }
    26	
    27	    /**
    28	     * Highly enchanted items -- enchantment level 5 or more -- add a 30 % risk
    29	     * surcharge on their own base premium.
    30	     */
    31	    public static int highEnchantmentSurcharge(List<Item> items) {
    32	        return surchargeOnItemsAtRisk(
    33	                items, ItemRiskSurcharges::isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
    34	    }
    35	
    36	    private static boolean isHighlyEnchanted(Item item) {
    37	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    38	    }
    39	
    40	    /**
    41	     * The MHPCO's scope rule for every item-specific surcharge, decided in one
    42	     * place: only the items carrying the risk are charged, each against its own
    43	     * base premium, and the amounts are summed into the policy premium.
    44	     */
    45	    private static int surchargeOnItemsAtRisk(
    46	            List<Item> items, Predicate<Item> carriesTheRisk, int surchargePercent) {
    47	        return items.stream()
    48	                .filter(carriesTheRisk)
    49	                .mapToInt(item -> MainItemPricing.basePremium(item) * surchargePercent / 100)
    50	                .sum();
    51	    }
    52	}
